pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 amount1, uint256 amount2) internal {
        vm.assume(amount1 != amount2);
        uint256 beforeDiff;
        try c.currentDifficulty() returns (uint256 __r) { beforeDiff = __r; } catch { return; }
        try c.AdjustDifficulty(amount1) {} catch { return; }
        try c.AdjustDifficulty(amount2) {} catch { return; }
        uint256 afterDiff;
        try c.currentDifficulty() returns (uint256 __r) { afterDiff = __r; } catch { return; }
        assertTrue(afterDiff == amount1 || afterDiff == amount2);
    }

    function testFuzz_test(uint256 amount1, uint256 amount2) public {
        _test(amount1, amount2);
    }

    receive() external payable {}
}
